// ──────────────────────────── tests ──────────────────────────────────────

Test("only changed prices are delivered", () =>
{
    var feed = new PriceFeed();
    var seen = new List<decimal>();
    using var sub = feed.Subscribe(p => seen.Add(p));
    feed.Publish(10m);
    feed.Publish(10m);
    feed.Publish(11m);
    Eq(seen, new[] { 10m, 11m });
});

Test("disposing unsubscribes only that handler", () =>
{
    var feed = new PriceFeed();
    var a = new List<decimal>();
    var b = new List<decimal>();
    var subA = feed.Subscribe(p => a.Add(p));
    feed.Subscribe(p => b.Add(p));
    feed.Publish(1m);
    subA.Dispose();
    feed.Publish(2m);
    Eq(a, new[] { 1m });
    Eq(b, new[] { 1m, 2m });
    Eq(feed.SubscriberCount, 1);
});

Test("disposing twice is harmless", () =>
{
    var feed = new PriceFeed();
    var sub = feed.Subscribe(_ => { });
    sub.Dispose();
    sub.Dispose();
    Eq(feed.SubscriberCount, 0);
});

Test("subscribers run in subscription order", () =>
{
    var feed = new PriceFeed();
    var log = new List<string>();
    feed.Subscribe(_ => log.Add("first"));
    feed.Subscribe(_ => log.Add("second"));
    feed.Publish(5m);
    Eq(log, new[] { "first", "second" });
});

Test("publishing with no subscribers does nothing (boundary)", () =>
{
    var feed = new PriceFeed();
    feed.Publish(3m);
    Eq(feed.SubscriberCount, 0);
});

