// ──────────────────────────── types ──────────────────────────────────────

class PriceFeed
{
    private event EventHandler<decimal>? PriceChanged;
    private decimal? _last;

    public int SubscriberCount => PriceChanged?.GetInvocationList().Length ?? 0;

    public IDisposable Subscribe(Action<decimal> handler)
    {
        EventHandler<decimal> h = (_, price) => handler(price);
        PriceChanged += h;
        return new Subscription(() => PriceChanged -= h);
    }

    public void Publish(decimal price)
    {
        if (_last == price) return;
        _last = price;
        PriceChanged?.Invoke(this, price);
    }
}

sealed class Subscription(Action onDispose) : IDisposable
{
    private Action? _onDispose = onDispose;
    public void Dispose()
    {
        _onDispose?.Invoke();
        _onDispose = null;
    }
}

drills.explanation:
Wrap the caller's action in ONE handler instance, subscribe it, and capture that same instance in the subscription's unsubscribe action:

```csharp
public IDisposable Subscribe(Action<decimal> handler)
{
    EventHandler<decimal> h = (_, price) => handler(price);
    PriceChanged += h;
    return new Subscription(() => PriceChanged -= h);
}
```

Because `h` is the exact delegate that was added, `-=` removes it (and only it). A nullable `_last` makes the first publish always notify. `GetInvocationList()` counts the subscribed delegates.
